(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-2-acute-vision-loss-quiz"]={"title":"Acute Vision Loss Quiz 1 — CMS I Exam 2","category":"Clinical Medicine and Surgery I","sem":"fall-2026","questions":[{"q":"A 77-year-old man is being treated for arteritic optic neuropathy. Why does the lecture describe it as a medical emergency?","choices":["It causes a stroke within hours","It raises intraocular pressure acutely","It detaches the retina","It raises intracranial pressure","Untreated, it leads to blindness"],"answer":4,"exp":"Correct, and the second eye is at risk. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 49"},{"q":"A 50-year-old man is told he has a disc at risk. What does this term describe?","choices":["A pale, atrophic disc","A small structural optic disc","A deeply cupped disc","A swollen disc from raised intracranial pressure","A disc with splinter haemorrhages"],"answer":1,"exp":"Correct, the anatomical association with the non-arteritic form. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 48"},{"q":"A 27-year-old patient is diagnosed with optic neuritis. What proportion of cases occur in women?","choices":["About 25 percent","About 90 percent","Sex distribution is not stated","About 75 percent","About 50 percent"],"answer":3,"exp":"Correct, in patients aged 18 to 45. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 23"},{"q":"A 69-year-old man with amaurosis fugax is investigated for a cardiac source. Which study does the lecture pair with that?","choices":["Carotid Doppler","Fluorescein angiography","Ocular ultrasound","Lumbar puncture","Echocardiogram"],"answer":4,"exp":"Correct; carotid Doppler is used for a carotid source. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 7"},{"q":"A 37-year-old man has papilledema. Which causes does the lecture list?","choices":["Tumour, trauma, infection, haemorrhage and vitamin A toxicity","Carotid emboli, cardiac emboli and retinal vascular spasm","Trabecular meshwork aging","Vitreous shrinkage","Autoimmune demyelination"],"answer":0,"exp":"Correct, all raising intracranial pressure. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 43"},{"q":"A 59-year-old man has acute angle closure. How soon after onset does the lecture perform the definitive procedure?","choices":["One to two days","Within the hour","After two weeks","Only if drops fail after a month","At the next routine appointment"],"answer":0,"exp":"Correct, after medical measures have lowered the pressure. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 20"},{"q":"A 31-year-old man with optic neuritis has an MRI. How many characteristic demyelinating lesions trigger the onward referral described?","choices":["At least one","At least five","Any number, if contrast enhancing","Lesion count does not affect referral","At least two"],"answer":4,"exp":"Correct, prompting neurology or neuro-ophthalmology referral. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 24"},{"q":"A 62-year-old woman has laser peripheral iridotomy planned. What does the lecture say the procedure achieves?","choices":["It removes carotid plaque","It drains cerebrospinal fluid","It dissolves an embolus lodged in the retinal artery","Fluid flows from the posterior to the anterior chamber","It reattaches the retina"],"answer":3,"exp":"Correct, bypassing the blocked circuit. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 20"},{"q":"A 41-year-old woman has acute papilledema. Which findings distinguish it from the chronic phase?","choices":["Optic nerve cupping","Haemorrhages and cotton wool spots","Disc elevation alone","Loss of the optic nerve axons","A cherry-red spot"],"answer":1,"exp":"Correct; the chronic phase lacks both. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 45"},{"q":"A 68-year-old man describes vision descending over one eye like a shade from above. What does the lecture attribute this to?","choices":["Raised intracranial pressure","Optic nerve demyelination","Trabecular meshwork disease","Vitreous traction","Retinal ischemia"],"answer":4,"exp":"Correct, when the loss descends over the field of one eye. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 6"},{"q":"A 65-year-old man has a retinal detachment. What timeframe does the lecture give for surgical repair?","choices":["At the next routine clinic","Immediately in every case, without exception","Urgently, or within a week depending on type","Within three months","Only if vision fails to improve"],"answer":2,"exp":"Correct. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 30"},{"q":"A 64-year-old woman asks how the two central retinal vascular occlusions compare in frequency. What does the lecture state?","choices":["Branch forms are more common than both","Vein occlusion is the more common","Artery occlusion is the more common","They are equally common","Neither occurs before age 70"],"answer":1,"exp":"Correct. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 32"},{"q":"A 78-year-old woman presents to a primary care clinic with sudden vision loss in one eye. What does the lecture direct the clinician to do?","choices":["Prescribe drops and review in a week","Order outpatient imaging and wait","Patch the eye and reassure","Refer only if pain develops","Refer emergently to ophthalmology"],"answer":4,"exp":"Correct, for anyone over 50 with sudden visual loss. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 51"},{"q":"A 64-year-old man has a retinal detachment. How does the lecture describe a retinal tear on examination?","choices":["Red and flame shaped","White and fluffy","Dark and pigmented centrally","Orange and crescent shaped","Pale and wedge shaped"],"answer":3,"exp":"Correct, against the elevated grey detached retina. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 29"},{"q":"A 67-year-old woman has a suspected retinal detachment. What advantage does the lecture give for ultrasound?","choices":["It visualises demyelinating lesions","It confirms raised intracranial pressure","It identifies the embolic source","It is more sensitive than the fundoscopic exam","It measures intraocular pressure"],"answer":3,"exp":"Correct, and it determines the type of detachment. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 29"},{"q":"A 60-year-old man presents with acute angle closure. Which topical agents does the lecture instil first?","choices":["Atropine drops","Antibiotic drops","Pilocarpine or timolol","Latanoprost or tafluprost","Prednisolone drops"],"answer":2,"exp":"Correct, a topical alpha-blocker or beta-blocker. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 20"},{"q":"A 26-year-old woman with optic neuritis asks why she needs a brain MRI when her sight is improving. What is the reason?","choices":["To find an underlying cause such as multiple sclerosis","To measure the intraocular pressure in both eyes","To confirm the retina is attached","To exclude a carotid embolus","To grade the optic nerve cupping"],"answer":0,"exp":"Correct; treating the episode alone can miss a larger problem. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 24"},{"q":"A 39-year-old man has papilledema. Which finding on lumbar puncture confirms the mechanism?","choices":["Xanthochromia","A normal opening pressure","An increased opening pressure","A raised white cell count","A low glucose level"],"answer":2,"exp":"Correct, confirming raised intracranial pressure. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 46"},{"q":"A 60-year-old man is being taught how to separate papilledema from glaucoma at the optic disc. What is the key difference?","choices":["Neither changes the disc","Only glaucoma affects the appearance of the disc","Papilledema pushes the disc out; glaucoma cups it in","Both cup the disc equally","Both elevate the disc equally"],"answer":2,"exp":"Correct, and the lecturer stressed how distinct they look. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 43"},{"q":"A 56-year-old man with non-arteritic anterior ischemic optic neuropathy has completed his workup. What does the lecture give as management?","choices":["Urgent surgical decompression","Lifelong pressure-lowering drops","Antiplatelet therapy alone","Observation and cardiovascular risk modification","A long-term high-dose oral corticosteroid course"],"answer":3,"exp":"Correct, once everything else has been excluded. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 52"},{"q":"A 65-year-old woman describes what the lecture calls fleeting blindness. Which term is this a synonym for?","choices":["Retinal detachment","Angle-closure glaucoma","Amaurosis fugax","Papilledema","Optic neuritis"],"answer":2,"exp":"Correct, monocular episodic visual loss. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 5"},{"q":"A 63-year-old man has chronic open-angle glaucoma. How does the lecture characterise its cause?","choices":["Raised intracranial pressure","Idiopathic optic nerve damage","Mechanical closure by the iris","An inflammatory arteritis","An embolic occlusion"],"answer":1,"exp":"Correct, from trabecular meshwork change with aging. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 15"},{"q":"A 52-year-old woman asks at what age retinal detachment becomes most common. What does the lecture say?","choices":["Between 40 and 60","Over age 80 only","After age 50","Under age 20","Between 18 and 45"],"answer":2,"exp":"Correct, as the vitreous shrinks with age. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 26"},{"q":"A 71-year-old woman with a central retinal artery occlusion asks about her wider risk. What does the lecture state?","choices":["Risk depends only on the intraocular pressure","Stroke risk rises at the onset of the occlusion","Stroke risk is unaffected","Risk is limited to the affected eye","Risk falls once vision is lost"],"answer":1,"exp":"Correct; plaque reaching the retina implies more upstream. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 37"},{"q":"A 70-year-old man has anterior ischemic optic neuropathy. How does the lecture describe the vision loss?","choices":["Sudden and painless, of side or central vision","Gradual and painless, developing over years","Sudden and severely painful","Transient with full recovery","Painful over hours to days"],"answer":0,"exp":"Correct. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 50"},{"q":"A 28-year-old woman with optic neuritis is referred. Which components does the lecture list in the ophthalmic examination?","choices":["Slit lamp, dilated fundoscopy and colour vision","Tonometry and gonioscopy","Carotid Doppler and echocardiography of the heart","Lumbar puncture and CT","Fluorescein angiography"],"answer":0,"exp":"Correct, with a neurological examination. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 24"},{"q":"A 74-year-old man has a central retinal artery occlusion. Which etiologies does the lecture list?","choices":["Arteriosclerosis, atherosclerosis and emboli","Venous thrombosis","Optic nerve demyelination","Vitreous traction and shrinkage of the retina","Raised intracranial pressure"],"answer":0,"exp":"Correct, the emboli being carotid or cardiac. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 37"},{"q":"A 67-year-old woman has a central retinal vein occlusion. Which findings does the lecture list on examination?","choices":["A normal disc with colour loss","Disc swelling, venous dilation and cotton wool spots","Pale retinal swelling with a cherry-red spot at the fovea","A hazy cornea and narrow angle","An elevated grey retina with folds"],"answer":1,"exp":"Correct, with retinal haemorrhages. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 34"},{"q":"A 61-year-old man is counselled after an episode of transient monocular vision loss. Which point does the lecture make central?","choices":["Only bilateral loss is concerning","Recovery means no workup is needed","The risk applies only over age 80","A transient ischemic attack warns of a stroke","A transient episode carries no further risk"],"answer":3,"exp":"Correct; it is a major warning sign. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 4"},{"q":"A 66-year-old man with amaurosis fugax does not recover fully. Which condition does the lecture say the remainder progress to?","choices":["Central retinal vein occlusion","Retinal detachment","Papilledema","Chronic open-angle glaucoma","Central retinal artery occlusion"],"answer":4,"exp":"Correct, a full blockage rather than a transient one. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 8"}]};
